#include <iostream>

class Shape {
public:
    virtual ~Shape() = default;
    virtual int area() const { return 0; }
};

class Circle : public Shape {
public:
    explicit Circle(int radius) : radius_(radius) {}
    int area() const override { return 3 * radius_ * radius_; }
private:
    int radius_;
};

class Square : public Shape {
public:
    explicit Square(int side) : side_(side) {}
    int area() const override { return side_ * side_; }
private:
    int side_;
};

int main() {
    int r = 0;
    int s = 0;
    std::cin >> r >> s;
    Shape* circle = new Circle(r);
    Shape* square = new Square(s);
    int total = circle->area() + square->area();
    delete circle;
    delete square;
    std::cout << total << std::endl;
    return 0;
}
